import type { ComprehensiveArea } from "./run-mode";

// Phase 35 (TFP-132, Decision 6): every Comprehensive report ends with what
// it did not test - a fixed, written statement per area, never generated by
// the model. The first use of honest-coverage's idea as a rule inside
// TestForge: a clean report must not read as "this area is fine".

export const NOT_TESTED_STATEMENTS: Record<ComprehensiveArea, readonly string[]> = {
    security: [
        "This was a passive run: it only loaded pages and read what came back, plus one request to a page that cannot exist to see the site's error page. No input was sent, so injection (SQL, script, command) and access control are untested.",
        "Logged-in pages were not checked: nothing here signed in, so anything behind a login is outside this run.",
        "Server configuration that isn't visible over HTTP - TLS settings, patch levels, secrets handling, logging - can't be verified from a browser.",
        "The table below lists the ASVS 5.0 chapters: those a passive run can reach, whether this run tested them, and those out of its reach.",
    ],
    accessibility: [
        "Automated scanning finds about half of WCAG issues: axe-core states it finds 57% of them on average. A clean scan does not mean the pages are accessible.",
        "Keyboard use, the screen-reader experience and whether the content is clear need a person to check.",
        "Items the scan could not decide are listed as needing manual review, not counted as passed.",
    ],
};

export function notCoveredPagesStatement(notCovered: readonly string[], pageCap: number): string | null {
    if (notCovered.length === 0) return null;
    return `${notCovered.length} known page${notCovered.length === 1 ? " was" : "s were"} beyond the ${pageCap}-page cap and not covered: ${notCovered.join(", ")}.`;
}
